// Neo4j graph memory connection
const neo4jDriver = neo4j.driver(
  'bolt://localhost:7687',
  neo4j.auth.basic('neo4j', 'bmparts2026')
);
async function neo4jRun(cypher, params = {}) {
  const session = neo4jDriver.session();
  try {
    const result = await session.run(cypher, params);
    return result.records.map(r => {
      const obj = {};
      r.keys.forEach(k => {
        const v = r.get(k);
        obj[k] = v && v.toNumber ? v.toNumber() : (v && v.properties ? v.properties : v);
      });
      return obj;
    });
  } finally {
    await session.close();
  }
}

