// --- Inventory Items Cache (avoids 429 rate limits) ---
let itemsCache = { items: [], lastFetched: 0, fetching: false };
const CACHE_TTL = 30 * 60 * 1000; // 30 minutes

async function refreshItemsCache() {
  if (itemsCache.fetching) return;
  itemsCache.fetching = true;
  console.log('[CACHE] Refreshing inventory items cache via Books API...');
  try {
    const token = await getAccessToken();
    const orgId = ZOHO_CONFIG.organizationId;
    const url = `https://www.zohoapis.${ZOHO_CONFIG.dataCenter}/books/v3/items`;
    let allItems = [];
    let currentPage = 1;
    let hasMore = true;

    while (hasMore && allItems.length < 10000) {
      const qParams = { organization_id: orgId, page: currentPage, per_page: 200, filter_by: 'Status.All' };
      const resp = await zohoRequest('GET', url, token, { params: qParams });
      const items = resp.data.items || [];
      allItems = allItems.concat(items);
      hasMore = resp.data.page_context?.has_more_page || false;
      currentPage++;
      if (items.length === 0) break;
      if (hasMore) await new Promise(r => setTimeout(r, 300));
    }

    itemsCache.items = allItems;
    itemsCache.lastFetched = Date.now();
    console.log(`[CACHE] Cached ${allItems.length} items (${currentPage - 1} pages)`);
  } catch (err) {
    console.error('[CACHE] Refresh failed:', err.message);
  } finally {
    itemsCache.fetching = false;
  }
}

// Pre-warm cache on startup (after 10s to let server bind and avoid rate limit contention)
setTimeout(() => refreshItemsCache(), 10000);

// Refresh cache periodically
setInterval(() => {
  if (Date.now() - itemsCache.lastFetched > CACHE_TTL) refreshItemsCache();
}, 60000);

