// Camera analyze — upload + instant Groq Vision analysis
app.post('/camera/analyze', cameraUpload.single('image'), async (req, res) => {
  if (!req.file) return res.status(400).json({ error: 'No image uploaded' });
  const question = req.body.question || 'Describe this image in rich detail. If there are people, describe each person: their face, hair, age estimate, ethnicity, expression, clothing, accessories, body language, and any distinguishing features. If you can identify or recognize anyone, say so. Describe the setting, objects, text, and any other notable elements.';
  console.log(`Camera analyze: ${req.file.filename} — "${question}"`);

  try {
    const sharp = require('sharp');
    const imgBuf = await sharp(req.file.path)
      .resize(1536, 1536, { fit: 'inside', withoutEnlargement: true })
      .jpeg({ quality: 92 })
      .toBuffer();
    const base64 = imgBuf.toString('base64');

    const groqKey = process.env.GROQ_KEY || '';
    const visionResp = await axios.post(
      'https://api.groq.com/openai/v1/chat/completions',
      {
        model: 'meta-llama/llama-4-scout-17b-16e-instruct',
        messages: [{
          role: 'user',
          content: [
            { type: 'text', text: question },
            { type: 'image_url', image_url: { url: `data:image/jpeg;base64,${base64}` } }
          ]
        }],
        max_tokens: 2048
      },
      {
        headers: { 'Authorization': `Bearer ${groqKey}`, 'Content-Type': 'application/json' },
        timeout: 60000
      }
    );
    const description = visionResp.data?.choices?.[0]?.message?.content || 'Could not analyze image.';
    console.log(`Camera analyze done: ${description.length} chars`);

    // Try to match against known people
    let personMatch = null;
    try { personMatch = await matchPerson(description); } catch (e) {}

    let fullDescription = description;
    if (personMatch) {
      fullDescription += `\n\n🔍 PERSON IDENTIFIED: ${personMatch.name} (confidence: ${personMatch.confidence}). ${personMatch.reason}`;
    }

    // Save analysis so Jess can read it via view_image
    const analysisData = {
      filename: req.file.filename,
      path: req.file.path,
      description: fullDescription,
      person_match: personMatch,
      question: question,
      timestamp: Date.now()
    };
    fs.writeFileSync(path.join(JESS_IMAGES_DIR, 'latest_analysis.json'), JSON.stringify(analysisData, null, 2));

    res.json({ ok: true, filename: req.file.filename, description: fullDescription, person_match: personMatch });
  } catch (e) {
    console.log('Camera analyze error:', e.response?.data || e.message);
    res.status(500).json({ error: `Vision analysis failed: ${e.message}` });
  }
});

// === People Recognition Database ===
const PEOPLE_DB = path.join(JESS_IMAGES_DIR, 'people.json');

function loadPeople() {
  try {
    if (fs.existsSync(PEOPLE_DB)) return JSON.parse(fs.readFileSync(PEOPLE_DB, 'utf-8'));
  } catch (e) {}
  return [];
}

function savePeople(people) {
  fs.writeFileSync(PEOPLE_DB, JSON.stringify(people, null, 2));
}

// Save a person (name + description from latest camera analysis)
app.post('/camera/remember', express.json(), (req, res) => {
  const { name, description } = req.body;
  if (!name || !description) return res.status(400).json({ error: 'name and description required' });

  const people = loadPeople();
  const existing = people.find(p => p.name.toLowerCase() === name.toLowerCase());
  if (existing) {
    // Update: append new description for better matching
    existing.descriptions.push(description);
    existing.updated = Date.now();
    existing.sightings = (existing.sightings || 1) + 1;
  } else {
    people.push({
      name: name,
      descriptions: [description],
      created: Date.now(),
      updated: Date.now(),
      sightings: 1
    });
  }
  savePeople(people);
  console.log(`People DB: saved "${name}" (${people.length} people total)`);
  res.json({ ok: true, name, total_people: people.length });
});

