        const days = periodDays[period] || 30;
        const startDate = new Date();
        startDate.setDate(startDate.getDate() - days);
        const dateStart = startDate.toISOString().split('T')[0];
        const dateEnd = new Date().toISOString().split('T')[0];
        const allInvoices = [];
        let pg = 1;
        let hasMore = true;
        while (hasMore) {
          const resp = await zohoRequest('GET', `https://www.zohoapis.${ZOHO_CONFIG.dataCenter}/books/v3/invoices`, token, { params: { organization_id: ZOHO_CONFIG.organizationId, date_start: dateStart, date_end: dateEnd, status: 'paid', per_page: 200, page: pg } });
          const invoices = resp.data.invoices || [];
          allInvoices.push(...invoices);
          hasMore = invoices.length === 200;
          pg++;
          if (pg > 10) break;
        }
        const itemSales = {};
        for (const inv of allInvoices) {
          const detailResp = await zohoRequest('GET', `https://www.zohoapis.${ZOHO_CONFIG.dataCenter}/books/v3/invoices/${inv.invoice_id}`, token, { params: { organization_id: ZOHO_CONFIG.organizationId } });
          const lineItems = detailResp.data.invoice?.line_items || [];
          for (const li of lineItems) {
            const key = li.item_id || li.sku;
            if (!itemSales[key]) { itemSales[key] = { item_id: li.item_id, sku: li.sku, name: li.name, quantity: 0, revenue: 0 }; }
            itemSales[key].quantity += li.quantity || 0;
            itemSales[key].revenue += li.item_total || 0;
          }
        }
        const sorted = Object.values(itemSales).sort((a, b) => b.quantity - a.quantity).slice(0, limit);
        result = { content: [{ type: 'text', text: JSON.stringify({ period, date_range: { start: dateStart, end: dateEnd }, invoice_count: allInvoices.length, top_sellers: sorted }, null, 2) }] };

      // ========== ZOHO ANALYTICS TOOL IMPLEMENTATIONS ==========

