// ========== CUSTOMER PORTAL API (STA Org) ==========
const STA_ORG_ID = process.env.ZOHO_STA_ORGANIZATION_ID || '857295887';

// STA items cache (separate from BMParts cache)
let staItemsCache = { items: [], lastFetched: 0, fetching: false };
const STA_CACHE_TTL = 30 * 60 * 1000; // 30 minutes

async function refreshStaItemsCache() {
  if (staItemsCache.fetching) return;
  staItemsCache.fetching = true;
  console.log('[PORTAL] Refreshing STA inventory items cache...');
  try {
    const token = await getAccessToken();
    const url = `https://www.zohoapis.${ZOHO_CONFIG.dataCenter}/inventory/v1/items`;
    let allItems = [];
    let currentPage = 1;
    let hasMore = true;

    while (hasMore && allItems.length < 10000) {
      const qParams = { organization_id: STA_ORG_ID, page: currentPage, per_page: 200, filter_by: 'Status.Active' };
      const resp = await zohoRequest('GET', url, token, { params: qParams });
      const items = resp.data.items || [];
      allItems = allItems.concat(items);
      hasMore = resp.data.page_context?.has_more_page || false;
      currentPage++;
      if (items.length === 0) break;
      if (hasMore) await new Promise(r => setTimeout(r, 300));
    }

    staItemsCache.items = allItems;
    staItemsCache.lastFetched = Date.now();
    console.log(`[PORTAL] Cached ${allItems.length} STA items (${currentPage - 1} pages)`);
  } catch (err) {
    console.error('[PORTAL] STA cache refresh failed:', err.message);
  } finally {
    staItemsCache.fetching = false;
  }
}

// Warm STA cache on startup (after 15s to stagger with BMParts cache)
setTimeout(() => refreshStaItemsCache(), 15000);
setInterval(() => {
  if (Date.now() - staItemsCache.lastFetched > STA_CACHE_TTL) refreshStaItemsCache();
}, 60000);

// Customer price list cache (synced hourly by sync-customer-pricelists.js)
let customerPricelistData = { pricebooks: {}, customers: {} };
function loadCustomerPricelists() {
  try {
    const fpath = require('path').join(__dirname, 'customer-pricelists.json');
    if (require('fs').existsSync(fpath)) {
      customerPricelistData = JSON.parse(require('fs').readFileSync(fpath, 'utf8'));
      console.log(`[PORTAL] Loaded customer pricelists: ${Object.keys(customerPricelistData.customers || {}).length} customers, ${Object.keys(customerPricelistData.pricebooks || {}).length} pricebooks`);
    }
  } catch (e) { console.error('[PORTAL] Failed to load customer pricelists:', e.message); }
}
loadCustomerPricelists();
// Reload every 5 minutes to pick up cron updates
setInterval(loadCustomerPricelists, 5 * 60 * 1000);

function applyPriceList(rate, pbId) {
  const pb = customerPricelistData.pricebooks[pbId];
  if (!pb || pb.type !== 'fixed_percentage') return rate;
  const pct = pb.percentage || 0;
  let adjusted = pb.is_increase ? rate * (1 + pct / 100) : rate * (1 - pct / 100);
  if (pb.rounding === 'round_to_dollar') adjusted = Math.round(adjusted);
  return Math.max(0, parseFloat(adjusted.toFixed(2)));
}

// ── Catalog static files & API rewrite (for Zoho Customer Portal iframe) ──
app.use('/catalog', express.static('/var/www/catalog', { index: 'index.html' }));
app.use('/product-images', express.static('/home/stan/Desktop/product-images', { maxAge: '7d' }));
// /api/portal/* proxy → /portal/* (so catalog HTML works with either base path)
app.use('/api/portal', (req, res) => {
  const url = `http://127.0.0.1:9091/portal${req.url}`;
  const opts = { method: req.method, headers: { ...req.headers, host: 'localhost' } };
  if (['POST','PUT','PATCH'].includes(req.method)) opts.data = req.body;
  axios({ ...opts, url, validateStatus: () => true, responseType: 'stream' })
    .then(r => { res.status(r.status); Object.entries(r.headers).forEach(([k,v]) => res.setHeader(k,v)); r.data.pipe(res); })
    .catch(e => res.status(502).json({ error: e.message }));
});

// GET /portal/items - Browse STA inventory (active, in-stock items)
app.get('/portal/items', (req, res) => {
  if (staItemsCache.items.length === 0 && staItemsCache.fetching) {
    return res.json({ items: [], loading: true, message: 'Loading catalog, please retry in a few seconds' });
  }
  if (staItemsCache.items.length === 0) {
    refreshStaItemsCache();
    return res.json({ items: [], loading: true, message: 'Loading catalog...' });
  }

  let items = staItemsCache.items;

  // Filter: only in-stock AND priced items by default
  const showAll = req.query.show_all === 'true';
  if (!showAll) {
    items = items.filter(i => (i.actual_available_stock || i.stock_on_hand || 0) > 0 && (i.rate || 0) > 0);
  }

  // Search filter
  const search = (req.query.search || '').toLowerCase().trim();
  if (search) {
    items = items.filter(i =>
      (i.name || '').toLowerCase().includes(search) ||
      (i.sku || '').toLowerCase().includes(search) ||
      (i.description || '').toLowerCase().includes(search) ||
      (i.category_name || '').toLowerCase().includes(search)
    );
  }

  // Category filter (applied after mapping, see below)
  const categoryFilter = (req.query.category || '').trim();

  // Normalize cf_category values to standard names
  const CATEGORY_NORMALIZE = {
    'airbags': 'Airbags',
    'bodywork': 'Bodywork',
    'cooling system': 'Cooling System',
    'drivetrain': 'Drivetrain',
    'electrical system': 'Electrical System',
    'engine': 'Engine',
    'lighting': 'Lighting',
    'oil/lubricants': 'Oil/Lubricants',
    'pdc': 'PDC',
    'pdc , distance system, cruise control': 'PDC',
    'steering system': 'Steering System',
    'suspension': 'Suspension',
    'transmission': 'Transmission',
    'trim': 'Trim',
  };
  function normalizeCategory(s) {
    if (!s) return '';
    return CATEGORY_NORMALIZE[s.toLowerCase().trim()] || '';
  }

  // Auto-categorize by product name keywords
  const CATEGORY_RULES = [
    ['Airbags', /\bairbag\b/i],
    ['Bodywork', /\b(bumper|fender(?! liner)|belly cover|bonnet (?:catch|lock|shock)|diffuser|deflector lip|chassis leg|stiffener|tow hook|splash cover|adaptor splash|lower bumper|number plate|windshield cover|boot push button|boot mat)\b/i],
    ['Cooling System', /\b(thermostat|radiator|water pump|water bottle|water pipe|expansion tank|cap for expansion|auxiliary water pump|cooling)\b/i],
    ['Drivetrain', /\b(propshaft|cradle|wheel hub|cv joint|driveshaft)\b/i],
    ['Electrical System', /\b(battery cable|power distr|coil pack|tpms|daytime running|led module|fragrance|slot card|key ring|eccentric shaft sensor|temperature sensor|exhaust pressure sensor|oil level sensor)\b/i],
    ['Engine', /\b(chain kit|charge pipe|connecting rod|crankshaft|crank pulley|engine oil|exhaust manifold|fuel|gasket|high pressure pump|injector|intake|oil pan|oil pump|oil filter|piston|spark plug|tappet cover|timing chain|turbo|vacuum pump|valve cover|valve stem|valvetronic|vanos|vvt|breather pipe|main seal|throttle|friction|v[- ]?belt|v brace|air filter|air duct)\b/i],
    ['Lighting', /\b(angel eyes|headlight|fog light|taillight|tail light|indicator.*module|reflector|side mirror indicator|xenon|h8 fog|led adaptive)\b/i],
    ['Oil/Lubricants', /\b(service kit|engine filter kit|pollen|cabin filter)\b/i],
    ['PDC', /\b(pdc|distance|cruise control|parking sensor)\b/i],
    ['Steering System', /\b(power steering|tie rod|control arm|steering)\b/i],
    ['Suspension', /\b(air shock|air suspension|airshock|shock absorber|shock mount|stabiliser link|german quality stabiliser)\b/i],
    ['Transmission', /\b(gearbox|handbrake|transmission)\b/i],
    ['Trim', /\b(air vent|cup holder|interior door|handle carrier|mirror cover|mirror glass|window mech|window switch|kidney grill|bonnet trim|boot shock|fender liner|headlight sprayer|headlight support|headlight bracket)\b/i],
  ];
  function autoCategory(name) {
    for (const [cat, regex] of CATEGORY_RULES) {
      if (regex.test(name)) return cat;
    }
    return '';
  }

  // Lighting subcategory rules
  const LIGHTING_SUB_RULES = [
    ['Headlights', /\b(headlight l$|headlight r$|headlight led l|headlight led r|headlight xe l|headlight xe r|headlight led lci)\b/i],
    ['Headlight Lens', /\bheadlight.*lens\b/i],
    ['Headlight Housings', /\bheadlight.*(housing|support|bracket)\b/i],
    ['LED Modules and Components', /\b(led module|ahl module|indicator.*module|daytime running|slot card|angel eyes.*led)\b/i],
    ['Fog Lights', /\b(fog light|h8 fog)\b/i],
    ['Tail Lights', /\b(taillight|tail light)\b/i],
    ['Xenon', /\b(xenon)\b/i],
    ['Angel Eyes', /\bangel eyes\b/i],
    ['Headlight Washers', /\bheadlight (washer|sprayer)\b/i],
    ['Reflectors', /\b(reflector|side mirror indicator)\b/i],
  ];
  function lightingSubcategory(name) {
    for (const [sub, regex] of LIGHTING_SUB_RULES) {
      if (regex.test(name)) return sub;
    }
    return '';
  }

  // Personalized pricing: lookup customer by email
  const customerEmail = (req.query.email || '').toLowerCase().trim();
  let customerInfo = null;
  let pbId = null;
  if (customerEmail && customerPricelistData.customers[customerEmail]) {
    customerInfo = customerPricelistData.customers[customerEmail];
    pbId = customerInfo.pricebook_id || null;
  }

  // Map to portal-friendly shape
  const mapped = items.map(i => {
    const baseRate = i.rate || 0;
    const cat = normalizeCategory(i.cf_category || i.category_name || '') || autoCategory(i.name || '');
    const entry = {
      item_id: i.item_id,
      sku: i.sku || '',
      name: i.name || '',
      description: i.description || '',
      rate: baseRate,
      stock: i.actual_available_stock || i.stock_on_hand || 0,
      category: cat,
      subcategory: cat === 'Lighting' ? lightingSubcategory(i.name || '') : '',
      image_url: i.cf_image_url || i.image_document_id || '',
      condition: i.cf_condition || '',
      unit: i.unit || ''
    };
    // Apply personalized price if customer has a price list
    if (pbId && baseRate > 0) {
      // Check for per-item custom rate first
      const pb = customerPricelistData.pricebooks[pbId];
      if (pb && pb.items && pb.items[i.item_id]) {
        entry.customer_rate = pb.items[i.item_id];
      } else {
        entry.customer_rate = applyPriceList(baseRate, pbId);
      }
      if (entry.customer_rate === baseRate) delete entry.customer_rate;
    }
    return entry;
  });

  // Fixed category list
  const PORTAL_CATEGORIES = ['Airbags','Bodywork','Cooling System','Drivetrain','Electrical System','Engine','Lighting','Oil/Lubricants','PDC','Steering System','Suspension','Transmission','Trim'];

  // Subcategory filter
  const subcategoryFilter = (req.query.subcategory || '').trim();

  // Apply category + subcategory filter after auto-categorization
  let finalItems = mapped;
  if (categoryFilter) finalItems = finalItems.filter(i => i.category.toLowerCase() === categoryFilter.toLowerCase());
  if (subcategoryFilter) finalItems = finalItems.filter(i => i.subcategory.toLowerCase() === subcategoryFilter.toLowerCase());

  // Lighting subcategories list
  const LIGHTING_SUBCATEGORIES = ['Headlights','Headlight Lens','Headlight Housings','LED Modules and Components','Fog Lights','Tail Lights','Xenon','Angel Eyes','Headlight Washers','Reflectors'];

  const response = {
    items: finalItems,
    count: finalItems.length,
    total_catalog: staItemsCache.items.length,
    categories: PORTAL_CATEGORIES,
    subcategories: { 'Lighting': LIGHTING_SUBCATEGORIES },
    cached_at: new Date(staItemsCache.lastFetched).toISOString(),
    loading: false
  };
  // Add customer pricing context if logged in
  if (customerInfo && pbId) {
    const pb = customerPricelistData.pricebooks[pbId];
    response.customer = {
      name: customerInfo.name,
      pricebook_name: customerInfo.pricebook_name,
      discount: pb && !pb.is_increase ? `${pb.percentage}%` : null,
    };
  }
  res.json(response);
});

