// GET /portal/customer - Lookup customer by email in STA org
app.get('/portal/customer', async (req, res) => {
  const email = (req.query.email || '').trim().toLowerCase();
  if (!email) {
    return res.status(400).json({ error: 'email parameter is required' });
  }
  try {
    const token = await getAccessToken();
    const url = `https://www.zohoapis.${ZOHO_CONFIG.dataCenter}/inventory/v1/contacts`;
    const resp = await zohoRequest('GET', url, token, {
      params: { organization_id: STA_ORG_ID, email }
    });
    const contacts = resp.data.contacts || [];
    const match = contacts.find(c => (c.email || '').toLowerCase() === email);
    if (match) {
      if (match.contact_type === 'vendor') {
        res.json({ found: false, message: 'This email is linked to a supplier account. Please use your customer email.' });
      } else {
        res.json({
          found: true,
          customer_id: match.contact_id,
          name: match.contact_name || match.company_name || '',
          email: match.email,
          company: match.company_name || '',
          contact_type: match.contact_type || ''
        });
      }
    } else {
      res.json({ found: false, message: 'No account found for this email. Please contact us to set up an account.' });
    }
  } catch (err) {
    console.error('[PORTAL] Customer lookup error:', err.message);
    res.status(500).json({ error: 'Failed to lookup customer', detail: err.message });
  }
});

// POST /portal/order - Create Sales Order in STA Zoho Inventory
app.post('/portal/order', async (req, res) => {
  const { customer_id, customer_name, items: orderItems, notes } = req.body;

  if (!customer_id) {
    return res.status(400).json({ error: 'customer_id is required. Use /portal/customer to lookup.' });
  }
  if (!orderItems || !Array.isArray(orderItems) || orderItems.length === 0) {
    return res.status(400).json({ error: 'items array is required with at least one item' });
  }

  // Validate each item has item_id and quantity
  for (const item of orderItems) {
    if (!item.item_id) return res.status(400).json({ error: `Missing item_id in order item` });
    if (!item.quantity || item.quantity < 1) return res.status(400).json({ error: `Invalid quantity for item ${item.item_id}` });
  }

  try {
    const token = await getAccessToken();
    const url = `https://www.zohoapis.${ZOHO_CONFIG.dataCenter}/inventory/v1/salesorders?organization_id=${STA_ORG_ID}`;

    const salesOrderData = {
      customer_id,
      date: new Date().toISOString().split('T')[0],
      line_items: orderItems.map(item => ({
        item_id: item.item_id,
        quantity: item.quantity,
        ...(item.rate !== undefined && { rate: item.rate })
      })),
      ...(notes && { notes })
    };

    console.log(`[PORTAL] Creating sales order for customer ${customer_id} with ${orderItems.length} items`);
    const resp = await zohoRequest('POST', url, token, {
      data: salesOrderData,
      headers: { 'Content-Type': 'application/json' }
    });

    const so = resp.data.salesorder || {};
    console.log(`[PORTAL] Sales order created: ${so.salesorder_number || 'unknown'}`);

    res.json({
      success: true,
      salesorder_id: so.salesorder_id,
      salesorder_number: so.salesorder_number,
      total: so.total,
      status: so.status,
      message: `Order ${so.salesorder_number} created successfully`
    });
  } catch (err) {
    console.error('[PORTAL] Order creation error:', err.message, err.response?.data);
    const detail = err.response?.data || err.message;
    res.status(500).json({ error: 'Failed to create order', detail });
  }
});

// POST /portal/draft-invoice - Create Draft Invoice in STA Zoho Inventory
app.post('/portal/draft-invoice', async (req, res) => {
  const { customer_id, customer_name, items: orderItems, notes } = req.body;

  if (!customer_id) {
    return res.status(400).json({ error: 'customer_id is required. Use /portal/customer to lookup.' });
  }
  if (!orderItems || !Array.isArray(orderItems) || orderItems.length === 0) {
    return res.status(400).json({ error: 'items array is required with at least one item' });
  }

  for (const item of orderItems) {
    if (!item.item_id) return res.status(400).json({ error: 'Missing item_id in order item' });
    if (!item.quantity || item.quantity < 1) return res.status(400).json({ error: `Invalid quantity for item ${item.item_id}` });
  }

  try {
    const token = await getAccessToken();
    const url = `https://www.zohoapis.${ZOHO_CONFIG.dataCenter}/inventory/v1/invoices?organization_id=${STA_ORG_ID}`;

    const invoiceData = {
      customer_id,
      date: new Date().toISOString().split('T')[0],
      is_draft: true,
      line_items: orderItems.map(item => ({
        item_id: item.item_id,
        quantity: item.quantity,
        ...(item.rate !== undefined && { rate: item.rate }),
        ...(item.name && { name: item.name })
      })),
      ...(notes && { notes }),
      ...(customer_name && { reference_number: `WEB-${Date.now()}` })
    };

    console.log(`[PORTAL] Creating draft invoice for customer ${customer_id} (${customer_name || 'unknown'}) with ${orderItems.length} items`);
    const resp = await zohoRequest('POST', url, token, {
      data: invoiceData,
      headers: { 'Content-Type': 'application/json' }
    });

    const inv = resp.data.invoice || {};
    console.log(`[PORTAL] Draft invoice created: ${inv.invoice_number || 'unknown'} total: ${inv.total}`);

    res.json({
      success: true,
      invoice_id: inv.invoice_id,
      invoice_number: inv.invoice_number,
      total: inv.total,
      status: inv.status,
      message: `Draft invoice ${inv.invoice_number} created successfully`
    });
  } catch (err) {
    console.error('[PORTAL] Draft invoice creation error:', err.message, err.response?.data);
    const detail = err.response?.data || err.message;
    res.status(500).json({ error: 'Failed to create draft invoice', detail });
  }
});

// ========================================
// Sale Prices JSON API (for Commerce header code)
// ========================================
app.get('/api/sale-prices', (req, res) => {
  const saleItems = {};
  (itemsCache.items || []).forEach(i => {
    const sp = parseFloat(i.cf_sale_price_unformatted || i.cf_sale_price) || 0;
    const stock = i.available_stock || i.stock_on_hand || 0;
    if (sp > 0 && stock > 0) {
      const mrp = parseFloat(i.label_rate) || 0;
      const displayRate = mrp > sp ? mrp : i.rate;
      saleItems[i.sku] = {
        name: i.name,
        rate: displayRate,
        sale_price: sp,
        discount_pct: displayRate > 0 ? Math.round(((displayRate - sp) / displayRate) * 100) : 0,
        image: i.cf_image_url || '',
        models: i.cf_modelsweb || '',
        item_id: i.item_id
      };
    }
  });
  res.set('Access-Control-Allow-Origin', '*');
  res.set('Cache-Control', 'public, max-age=300');
  res.json(saleItems);
});

// ========================================
// RSS Feed - Sale Items (for Zoho Social)
// ========================================
app.get('/rss/specials', (req, res) => {
  const items = itemsCache.items.filter(i => {
    const sp = parseFloat(i.cf_sale_price_unformatted || i.cf_sale_price) || 0;
    const stock = i.available_stock || i.stock_on_hand || 0;
    return sp > 0 && stock > 0;
  });

  const now = new Date().toUTCString();
  let rss = `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:media="http://search.yahoo.com/mrss/">
  <channel>
    <title>BMParts Specials</title>
    <link>https://www.partsza.co.za</link>
    <description>BMW Parts on Special - PartsZA South Africa</description>
    <lastBuildDate>${now}</lastBuildDate>
    <language>en-za</language>
`;

  items.forEach(item => {
    const rate = item.rate || 0;
    const salePrice = parseFloat(item.cf_sale_price_unformatted || item.cf_sale_price) || 0;
    const discount = Math.round(rate - salePrice);
    const discountPct = rate > 0 ? Math.round((discount / rate) * 100) : 0;
    const models = item.cf_modelsweb || '';
    const sku = item.sku || '';
    const name = item.name || 'BMW Part';
    const imageUrl = item.cf_image_url || item.image_url || '';

    const fullPost = `🔥 SPECIAL OFFER 🔥

BMW ${name}
${models ? '📍 Fits: ' + models : ''}

Was R${rate} → NOW R${salePrice} 🏷️
Save R${discount} (${discountPct}% OFF!)

✅ Brand New | OEM Quality
✅ In Stock & Ready to Ship
📦 Nationwide Delivery

🛒 Shop: https://www.partsza.co.za

#BMWParts #BMWSpecials #BMW #CarParts #PartsZA #SouthAfrica #OEMParts`;

    // Use SKU + sale price as GUID so same item won't re-post unless price changes
    const guid = `bmparts-special-${sku}-${salePrice}`;

    rss += `    <item>
      <title>${escapeXml(fullPost)}</title>
      <description>${escapeXml(fullPost)}</description>
      <link>https://www.partsza.co.za</link>
      <guid isPermaLink="false">${guid}</guid>
      <pubDate>${now}</pubDate>
${imageUrl ? '      <media:content url="' + escapeXml(imageUrl) + '" medium="image" />\n      <enclosure url="' + escapeXml(imageUrl) + '" type="image/jpeg" />\n' : ''}    </item>
`;
  });

  rss += `  </channel>
</rss>`;

  res.set('Content-Type', 'application/rss+xml; charset=utf-8');
  res.send(rss);
});

function escapeXml(s) {
  return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&apos;');
}

const PORT = process.env.PORT || 9091;
app.listen(PORT, () => {
  console.log(`Zoho MCP Server v2.1.0 listening on port ${PORT}`);
});

